S = "Hakeem Force Academy"
QS = [
(S, "Which of the following countries is NOT a member of the Economic Cooperation Organization (ECO)?", ["Iran", "Uzbekistan", "Saudi Arabia", "Turkey"], 2, "ECO members are Pakistan, Iran, Turkey, Afghanistan, Azerbaijan, Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan and Uzbekistan. Saudi Arabia is not among them.", "ECO has ten members and its secretariat is in Tehran.", [1302]),
(S, "What is the antonym of the word 'ecstasy'?", ["Rapture", "Misery", "Elation", "Delight"], 1, "Ecstasy means overwhelming joy, so its opposite is deep unhappiness, which is misery. Rapture, elation and delight are its synonyms.", "Agony and despair are also opposites of ecstasy.", [580]),
(S, "What is the meaning (synonym) of the word 'ecstasy'?", ["Overwhelming joy", "Deep sorrow", "Mild anger", "Boredom"], 0, "Ecstasy is a state of intense happiness or delight. Rapture is a close synonym.", "The adjective form is ecstatic, meaning extremely happy.", [3759, 3973]),
(S, "Abdul Sattar Edhi, the famous humanitarian known as the Angel of Mercy, belonged to which country?", ["Pakistan", "Bangladesh", "India", "Afghanistan"], 0, "Edhi spent his life in Pakistan and founded the Edhi Foundation in Karachi. He is regarded as one of the greatest humanitarians of Pakistan.", "Edhi died in Karachi on 8 July 2016.", [1668]),
(S, "Where was Abdul Sattar Edhi born?", ["Karachi", "Lahore", "Bantva, Gujarat (British India)", "Multan"], 2, "Edhi was born in 1928 in Bantva in Gujarat, British India, and migrated to Pakistan after Partition.", "His family belonged to the Memon community.", [1273]),
(S, "Which of these international days is observed by the United Nations in January (on 24 January)?", ["International Day of Education", "World Refugee Day", "International Day for the Eradication of Poverty", "Mother's Day"], 0, "The International Day of Education is observed on 24 January. World Refugee Day is 20 June and the Day for the Eradication of Poverty is 17 October.", "Mother's Day is not a UN day and falls in May in most countries.", [2499]),
(S, "Who developed the first effective polio vaccine?", ["Louis Pasteur", "Jonas Salk", "Edward Jenner", "Alexander Fleming"], 1, "Jonas Salk developed the first effective inactivated polio vaccine, announced in 1955. Albert Sabin later developed the oral vaccine.", "Pakistan and Afghanistan are the only countries where wild polio is still endemic.", [5224, 5243]),
(S, "If one egg takes 2 minutes to boil, how many minutes will 5 eggs take when boiled together in the same pot?", ["10 minutes", "5 minutes", "2 minutes", "7 minutes"], 2, "Eggs boil at the same time in the same pot, so the time does not depend on the number of eggs. All 5 eggs take 2 minutes.", "This is a classic logic puzzle where the obvious multiplication is wrong.", [2392]),
(S, "Akbar is older than Ahmad and Umair is older than Akbar. Who is the eldest?", ["Ahmad", "Akbar", "Umair", "Cannot be determined"], 2, "Umair is older than Akbar, and Akbar is older than Ahmad. So the order is Umair, Akbar, Ahmad and Umair is the eldest.", "Chain the comparisons to rank all persons.", [1731]),
(S, "If Akbar is elder than Ahmad and Adnan is elder than Akbar, then who is the eldest?", ["Adnan", "Akbar", "Ahmad", "Cannot be determined"], 0, "Adnan is elder than Akbar, and Akbar is elder than Ahmad. So Adnan is the eldest.", "The youngest in this chain is Ahmad.", [2373]),
(S, "For how many years is the President of Pakistan elected?", ["3 years", "4 years", "5 years", "6 years"], 2, "Under the 1973 Constitution the President holds office for a term of five years.", "The President is elected by an electoral college of the Senate, National Assembly and provincial assemblies.", [346]),
(S, "For how many years is the Prime Minister of Pakistan elected?", ["4 years", "5 years", "3 years", "6 years"], 1, "The National Assembly has a term of five years and the Prime Minister, elected by it, serves for the term of the Assembly unless removed earlier.", "The Constitution does not set a separate fixed term for the Prime Minister.", [814]),
(S, "Who elects the President of Pakistan?", ["Only the National Assembly", "Only the Senate", "The Chief Justice of Pakistan", "An electoral college of the Senate, National Assembly and provincial assemblies"], 3, "The President is elected indirectly by an electoral college made up of members of the Senate, the National Assembly and the four provincial assemblies.", "Asif Ali Zardari was elected President for a second time in March 2024.", [1388, 5041]),
(S, "In whose government were the non-party based elections held in Pakistan in 1985?", ["Zulfikar Ali Bhutto", "Ayub Khan", "General Zia-ul-Haq", "Pervez Musharraf"], 2, "General Zia-ul-Haq held non-party elections in February 1985. Muhammad Khan Junejo became Prime Minister after them.", "The 1985 assemblies passed the Eighth Amendment.", [984]),
(S, "Who was the Prime Minister of Pakistan when the first constitution was enforced in 1956?", ["Liaquat Ali Khan", "Chaudhry Muhammad Ali", "Khawaja Nazimuddin", "H. S. Suhrawardy"], 1, "The 1956 Constitution came into force on 23 March 1956 while Chaudhry Muhammad Ali was Prime Minister. He was also its main architect.", "Iskander Mirza became the first President under it.", [5391]),
(S, "In which pact were separate electorates for Muslims granted?", ["Lucknow Pact 1916", "Nehru Report 1928", "Simla Agreement 1972", "Liaquat-Nehru Pact 1950"], 0, "Under the Lucknow Pact of 1916 the Congress accepted the Muslim League's demand for separate electorates for Muslims.", "Separate electorates were first given in the Morley-Minto Reforms of 1909.", [2638]),
(S, "What is the main source of electricity generation in Pakistan today?", ["Hydel (hydropower)", "Natural gas", "Coal", "Wind"], 0, "Recent data for 2025 show hydel power as the largest single source, around 39 percent in some months. RLNG and nuclear follow.", "In earlier decades thermal (oil and gas) plants produced most of Pakistan's electricity.", [3731, 821, 3413]),
(S, "What is a set that has no element called?", ["Singleton set", "Universal set", "Null (empty) set", "Finite set"], 2, "A set with no element is called the null set or empty set and is written as a circle with a slash or as curly brackets with nothing inside.", "The empty set is a subset of every set.", [3331]),
(S, "What is a set with exactly one element called?", ["Null set", "Singleton set", "Power set", "Universal set"], 1, "A set containing only one element, such as the set containing 5 alone, is called a singleton set.", "A singleton set has exactly two subsets.", [3332]),
(S, "If every element of set A is also an element of set B, then A is called what of B?", ["Superset", "Complement", "Subset", "Union"], 2, "When all elements of A belong to B, A is a subset of B, written A is contained in B.", "B is then called a superset of A.", [2383]),
(S, "Which one is different from the rest: cow, snake, elephant, monkey?", ["Cow", "Snake", "Elephant", "Monkey"], 1, "Cow, elephant and monkey are mammals, while a snake is a reptile.", "Mammals are warm-blooded and feed milk to their young.", [4773]),
(S, "In which country did Pakistan open its first embassy?", ["Saudi Arabia", "Turkey", "Iran", "China"], 2, "Pakistan opened its first embassy in Iran, which was also among the first countries to recognise Pakistan in 1947.", "Some sources differ on early diplomatic firsts, but Iran is the answer given in most Pakistani textbooks and tests.", [15, 649, 4554]),
(S, "What is the antonym of the word 'embellish'?", ["Adorn", "Decorate", "Disfigure", "Beautify"], 2, "To embellish is to make something more attractive by adding decoration. Its opposite is to disfigure or spoil.", "Embellish can also mean to add exaggerated details to a story.", [1086]),
(S, "What is the meaning of the word 'embellish'?", ["To make more attractive by adding decoration", "To destroy", "To hide", "To measure"], 0, "Embellish means to decorate or beautify something, or to add extra details to a story.", "Adorn and ornament are synonyms of embellish.", [3783]),
(S, "When was the partition of Bengal enforced by Lord Curzon?", ["1857", "1905", "1911", "1947"], 1, "Lord Curzon divided Bengal into East Bengal and Assam and West Bengal, and the partition took effect on 16 October 1905.", "The partition was annulled in 1911.", [4297]),
(S, "On which date did the Indian Independence Act 1947 come into effect, creating Pakistan and India?", ["3 June 1947", "14 August 1947", "15 August 1947", "18 July 1947"], 2, "The Act was passed by the British Parliament on 18 July 1947 and the two dominions came into being on 15 August 1947 at midnight.", "Pakistan celebrates independence on 14 August.", [2882]),
(S, "How many articles are there in the English language?", ["2", "3", "4", "5"], 1, "The English articles are a, an and the. A and an are indefinite and the is definite.", "Candidates often wrongly say 2, forgetting that a and an are separate forms.", [350]),
(S, "Which of the following are the vowels of the English alphabet?", ["A, E, I, O, U", "A, E, I, O, Y", "A, E, O, U, W", "E, I, O, U, Y"], 0, "The five vowel letters of English are A, E, I, O and U.", "The English alphabet has 26 letters, so 21 are consonants.", [3159]),
(S, "What is the synonym of 'enigmatic'?", ["Obvious", "Mysterious", "Cheerful", "Simple"], 1, "Enigmatic describes something puzzling and hard to understand, which is mysterious.", "The noun enigma means a puzzle or riddle.", [3340, 3974]),
(S, "Completely is to what, as a synonym? Choose the word closest in meaning to 'entirely'.", ["Partly", "Slightly", "Completely", "Rarely"], 2, "Entirely means in every part or fully, the same as completely.", "Wholly and totally are also synonyms.", [1913, 1182]),
(S, "If RAT is coded as TAR (letters reversed), then what is FAT equal to?", ["TAF", "FTA", "ATF", "AFT"], 0, "RAT becomes TAR by reversing the order of letters. Reversing FAT gives TAF.", "Reversal codes are the simplest letter codes.", [2394]),
(S, "In trigonometry, what is tan x equal to?", ["cos x divided by sin x", "sin x divided by cos x", "1 divided by sin x", "1 divided by cos x"], 1, "Tangent is the ratio of sine to cosine, so tan x equals sin x divided by cos x.", "Cot x is the reciprocal of tan x.", [3248]),
(S, "What is the value of 2 + 2/2?", ["2", "1", "4", "3"], 3, "Division comes first: 2/2 = 1. Then 2 + 1 = 3.", "BODMAS gives division priority over addition.", [3281]),
(S, "What is cosecant x equal to?", ["1 divided by cos x", "1 divided by sin x", "1 divided by tan x", "sin x divided by cos x"], 1, "Cosecant is the reciprocal of sine, so cosec x = 1 / sin x.", "Sec x = 1 / cos x and cot x = 1 / tan x.", [3370]),
(S, "What type of equation is 6x - 5x - 7 = 0?", ["Quadratic", "Cubic", "Linear", "Exponential"], 2, "Simplifying gives x - 7 = 0, which has highest power 1 of x, so it is linear and gives x = 7.", "A linear equation in one variable has exactly one root.", [4083]),
(S, "In whose era was the Battle of Yamama fought?", ["Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Usman (RA)", "Hazrat Ali (RA)"], 0, "The Battle of Yamama was fought in 11-12 AH against the false prophet Musaylima during the caliphate of Hazrat Abu Bakr (RA).", "Many Huffaz died there, which led to the first compilation of the Quran.", [2769]),
(S, "Who headed the committee for the collection of the Holy Quran in the era of Hazrat Abu Bakr (RA)?", ["Hazrat Zaid bin Thabit (RA)", "Hazrat Ali (RA)", "Hazrat Abdullah bin Masud (RA)", "Hazrat Ubay bin Kab (RA)"], 0, "Hazrat Abu Bakr (RA) appointed Zaid bin Thabit, the Prophet's scribe of revelation, to collect the Quran into one volume.", "Zaid also led the committee in the era of Hazrat Usman (RA).", [5381]),
(S, "The Holy Prophet Muhammad (PBUH) belongs to the descendants of which prophet?", ["Hazrat Musa (AS)", "Hazrat Essa (AS)", "Hazrat Ismail (AS)", "Hazrat Yaqub (AS)"], 2, "The Prophet (PBUH) descended from Hazrat Ismail (AS), son of Hazrat Ibrahim (AS), through the Quraysh.", "Hazrat Essa (AS) had no father and no direct descendants.", [2099]),
(S, "How many end points does a ray have?", ["0", "1", "2", "3"], 1, "A ray starts at one fixed point and extends endlessly in one direction, so it has one end point.", "A line segment has two end points and a line has none.", [2138]),
(S, "How many enemy soldiers marched against the Muslims in the Battle of Uhud?", ["313", "1000", "3000", "10000"], 2, "The Quraysh army at Uhud numbered about 3000 soldiers, while the Muslims were about 700.", "The Quraysh were led by Abu Sufyan.", [4152]),
(S, "Which uncle of Prophet Muhammad (PBUH) was among his bitter enemies?", ["Abu Lahab", "Abu Talib", "Hazrat Hamza", "Hazrat Abbas"], 0, "Abu Lahab (Abdul Uzza) strongly opposed the Prophet (PBUH) and a Surah of the Quran is named after him. Abu Jahal was not his uncle.", "Surah Al-Masad condemns Abu Lahab.", [4946]),
(S, "Which country connects Asia and Europe?", ["Turkey", "Iran", "Greece", "Egypt"], 0, "Turkey lies partly in Asia (Anatolia) and partly in Europe (Thrace), separated by the Bosphorus strait.", "Istanbul is the only major city located on two continents.", [4493]),
]
